const labels={PET:{m:2,formula:'(C₁₀H₈O₄)ₙ'},PTT:{m:3,formula:'(C₁₁H₁₀O₄)ₙ'},PBT:{m:4,formula:'(C₁₂H₁₂O₄)ₙ'},PMMA:{formula:'(C₅H₈O₂)ₙ'}};
const sub={2:'₂',3:'₃',4:'₄'};
function canvas(inner,label,height=230){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 ${height}" role="img" aria-label="${label}" class="polymer-svg"><title>${label}</title><g fill="none" stroke="#263b2c" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">${inner.lines}</g><g fill="#263b2c" font-family="Arial, sans-serif" font-size="25" text-anchor="middle">${inner.text}</g></svg>`}
function polyester(m){return canvas({lines:`<path d="M52 51 H40 V165 H52 M652 51 H664 V165 H652 M20 108 H72 M107 108 H125 M232 108 H250 M284 108 H314 M352 108 H395 M515 108 H582 M614 108 H684 M329 88 V58 M337 88 V58 M594 88 V58 M602 88 V58 M395 108 L425 56 H485 L515 108 L485 160 H425 Z M407 105 L431 66 M437 149 H479 M502 108 L480 70"/>`,text:`<text x="90" y="117">O</text><text x="179" y="117">(CH₂)${sub[m]}</text><text x="267" y="117">O</text><text x="333" y="117">C</text><text x="333" y="46">O</text><text x="598" y="117">C</text><text x="598" y="46">O</text><text x="682" y="184" font-size="20">n</text>`},`聚酯重复单元：O-(CH2)${m}-O-C(=O)-对苯环-C(=O)，方括号n表示重复次数`)}
function pmma(){return canvas({lines:`<path d="M90 16 H77 V310 H90 M610 16 H623 V310 H610 M55 104 H182 M245 104 H347 M375 104 H645 M361 84 V49 M361 124 V179 M381 198 H426 M381 206 H426 M361 218 V261"/>`,text:`<text x="214" y="113">CH₂</text><text x="361" y="113">C</text><text x="361" y="35">CH₃</text><text x="361" y="210">C</text><text x="446" y="210">O</text><text x="361" y="291">O–CH₃</text><text x="642" y="327" font-size="20">n</text>`},'PMMA重复单元：碳碳主链CH2-C，取代基为甲基和甲氧羰基',350)}
export function structureFigure(abbr){const x=labels[abbr];if(!x)return '';const source=abbr==='PMMA'?'https://wrap.warwick.ac.uk/id/eprint/106480/1/WRAP_Theses_Pring_1989.pdf':'https://doi.org/10.1021/acs.macromol.4c00683';const note=abbr==='PMMA'?'碳碳主链上的两个侧基分别为甲基和酯基；MMA 单体的碳碳双键已在聚合时打开。':`酯基和对苯环构成共同骨架；${abbr} 的二醇片段含 ${x.m} 个亚甲基。PET / PTT / PBT 分别为 2 / 3 / 4 个。`;return `<figure class="structure-figure"><div class="structure-figure-top"><strong>${abbr} · 理想重复单元</strong><span>二维结构示意</span></div><div class="structure-image">${abbr==='PMMA'?pmma():polyester(x.m)}</div><figcaption><div class="repeat-formula"><span>重复单元化学式</span><strong>${x.formula}</strong></div><p>${note}</p><small>n 表示重复次数；这里表示理想线性均聚物，不代表实际牌号的全部组成、链端或立体构型，也不是单体分子式。</small><a href="${source}" target="_blank" rel="noopener noreferrer">结构参考 ↗</a></figcaption></figure>`}
